272	  const customerId = useCustomerId();
273	  const [searchParams, { stringify: stringifySearchParams }] = useSearchParams();
274	
275	  /**************** Page State ****************/
276	  // Offset into the applied-filter chip window, shared by the desktop bar and the mobile row.
277	  // Window size is breakpoint-dependent — see `chipsPerPage`.
278	  const [chipOffset, setChipOffset] = useState(0);
279	  const [sortOpen, setSortOpen] = useState(false);
280	  const [wishlistLoading, setWishlistLoading] = useState<string[]>([]);
281	  const [searchByInventory, setSearchByInventory] = useState<string | number | null>(null);
282	
283	  const urlParams = new URLSearchParams(location.search);
284	  const searchQuery = urlParams.get('q');
285	  const isSearch = !!searchQuery;
286	
287	  if (params.categoryId) {
288	    searchParams._refine.push(`cgid=${params.categoryId}`);
289	  }
290	
291	  /**************** Mutation Actions ****************/
292	  const { mutateAsync: createCustomerProductListItem } = useShopperCustomersMutation('createCustomerProductListItem');
293	  const { mutateAsync: deleteCustomerProductListItem } = useShopperCustomersMutation('deleteCustomerProductListItem');
294	
295	  /**************** Query Actions ****************/
296	  // _refine is an invalid param for useProductSearch, we don't want to pass it to API call
297	  const { _refine, ...restOfParams } = searchParams;
298	
299	  const refine = searchByInventory ? [..._refine, `ilids=${searchByInventory}`] : _refine;
300	
301	  const {
302	    isLoading,
303	    isFetched,
304	    isRefetching,
305	    data: productSearchResult,
306	  } = useProductSearch(
307	    {
308	      parameters: {
309	        ...restOfParams,
310	        perPricebook: true,
311	        allVariationProperties: true,
312	        allImages: true,
313	        expand: ['promotions', 'variations', 'prices', 'images', 'page_meta_tags', 'custom_properties'],
314	        refine,
315	      },
316	    },
317	    {
318	      keepPreviousData: true,
319	    },
320	  );
321	
322	  const { error, data: category } = useCategory(
323	    {
324	      parameters: {
325	        // `enabled` below gates the actual request on a real categoryId; the fallback here only
326	        // satisfies the hook's own parameter type (which does not accept `undefined`) for the
327	        // render where categoryId isn't present yet (e.g. a search-query route).
328	        id: params.categoryId ?? '',
329	      },
330	    },
331	    {
332	      enabled: !isSearch && !!params.categoryId,
333	    },
334	  );
335	
336	  // SFCC-847 — persisted list of category radio options for the drawer's Category facet.
337	  // category.categories (OOTB useCategory data) only lists the CURRENT category's children —
338	  // once the shopper navigates into a leaf category (no children of its own), it comes back
339	  // empty and the radio list would otherwise vanish. Persisting the last non-empty list keeps
340	  // every sibling option available across that navigation. Sources from the same real, correct
341	  // OOTB data category.categories already provides, just surviving the navigation. Also
342	  // seeded from localStorage on mount so a hard refresh on a leaf category page doesn't lose
343	  // it either — in-memory state alone only survives client-side navigation, not a real reload.
344	  const [categoryOptions, setCategoryOptions] = useState<{ id: string; name?: string }[] | undefined>(() => {
345	    if (isServer) return undefined;
346	    try {
347	      const stored = window.localStorage.getItem(CATEGORY_OPTIONS_STORAGE_KEY);
348	      return stored ? JSON.parse(stored) : undefined;
349	    } catch {
350	      return undefined;
351	    }
352	  });
353	  useEffect(() => {
354	    if (category?.categories && category.categories.length > 0) {
355	      setCategoryOptions(category.categories);
356	      if (!isServer) {
357	        // Persistence is best-effort — quota exceeded, private browsing, or disabled storage
358	        // must not break category loading; the in-memory setCategoryOptions above already
359	        // covers this render regardless of whether the write below succeeds.
360	        try {
361	          window.localStorage.setItem(CATEGORY_OPTIONS_STORAGE_KEY, JSON.stringify(category.categories));
362	        } catch {
363	          // Ignore — see comment above.
364	        }
365	      }
366	    }
367	  }, [category]);
368	
369	  /**************** Error Handling ****************/
370	  const errorStatus = (error as { response?: { status?: number } } | null)?.response?.status;
371	  switch (errorStatus) {
372	    case undefined:
373	      // No Error.
374	      break;
375	    case 404:
376	      throw new HTTPNotFound('Category Not Found.');
377	    default:
378	      throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
379	  }
380	
381	  /**************** Response Handling ****************/
382	  if (res) {
383	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
384	  }
385	
386	  // Reset scroll position when `isRefetching` becomes `true`.
387	  useEffect(() => {
388	    isRefetching && window.scrollTo(0, 0);
389	  }, [isRefetching]);

