const einstein = useEinstein();
const dataCloud = useDataCloud();
const activeData = useActiveData();
const { res } = useServerContext();
const customerId = useCustomerId();
const [searchParams, { stringify: stringifySearchParams }] = useSearchParams();

/**************** Page State ****************/
// Offset into the applied-filter chip window, shared by the desktop bar and the mobile row.
// Window size is breakpoint-dependent — see `chipsPerPage`.
const [chipOffset, setChipOffset] = useState(0);
const [sortOpen, setSortOpen] = useState(false);
const [wishlistLoading, setWishlistLoading] = useState<string[]>([]);
const [searchByInventory, setSearchByInventory] = useState<string | number | null>(null);

const urlParams = new URLSearchParams(location.search);
const searchQuery = urlParams.get('q');
const isSearch = !!searchQuery;

if (params.categoryId) {
  searchParams._refine.push(`cgid=${params.categoryId}`);
}

/**************** Mutation Actions ****************/
const { mutateAsync: createCustomerProductListItem } = useShopperCustomersMutation('createCustomerProductListItem');
const { mutateAsync: deleteCustomerProductListItem } = useShopperCustomersMutation('deleteCustomerProductListItem');

/**************** Query Actions ****************/
// _refine is an invalid param for useProductSearch, we don't want to pass it to API call
const { _refine, ...restOfParams } = searchParams;

const refine = searchByInventory ? [..._refine, `ilids=${searchByInventory}`] : _refine;

const {
  isLoading,
  isFetched,
  isRefetching,
  data: productSearchResult,
} = useProductSearch(
  {
    parameters: {
      ...restOfParams,
      perPricebook: true,
      allVariationProperties: true,
      allImages: true,
      expand: ['promotions', 'variations', 'prices', 'images', 'page_meta_tags', 'custom_properties'],
      refine,
    },
  },
  {
    keepPreviousData: true,
  },
);

const { error, data: category } = useCategory(
  {
    parameters: {
      // `enabled` below gates the actual request on a real categoryId; the fallback here only
      // satisfies the hook's own parameter type (which does not accept `undefined`) for the
      // render where categoryId isn't present yet (e.g. a search-query route).
      id: params.categoryId ?? '',
    },
  },
  {
    enabled: !isSearch && !!params.categoryId,
  },
);

// SFCC-847 — persisted list of category radio options for the drawer's Category facet.
// category.categories (OOTB useCategory data) only lists the CURRENT category's children —
// once the shopper navigates into a leaf category (no children of its own), it comes back
// empty and the radio list would otherwise vanish. Persisting the last non-empty list keeps
// every sibling option available across that navigation. Sources from the same real, correct
// OOTB data category.categories already provides, just surviving the navigation. Also
// seeded from localStorage on mount so a hard refresh on a leaf category page doesn't lose
// it either — in-memory state alone only survives client-side navigation, not a real reload.
const [categoryOptions, setCategoryOptions] = useState<{ id: string; name?: string }[] | undefined>(() => {
  if (isServer) return undefined;
  try {
    const stored = window.localStorage.getItem(CATEGORY_OPTIONS_STORAGE_KEY);
    return stored ? JSON.parse(stored) : undefined;
  } catch {
    return undefined;
  }
});
useEffect(() => {
  if (category?.categories && category.categories.length > 0) {
    setCategoryOptions(category.categories);
    if (!isServer) {
      // Persistence is best-effort — quota exceeded, private browsing, or disabled storage
      // must not break category loading; the in-memory setCategoryOptions above already
      // covers this render regardless of whether the write below succeeds.
      try {
        window.localStorage.setItem(CATEGORY_OPTIONS_STORAGE_KEY, JSON.stringify(category.categories));
      } catch {
        // Ignore — see comment above.
      }
    }
  }
}, [category]);

/**************** Error Handling ****************/
const errorStatus = (error as { response?: { status?: number } } | null)?.response?.status;
switch (errorStatus) {
  case undefined:
    // No Error.
    break;
  case 404:
    throw new HTTPNotFound('Category Not Found.');
  default:
    throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
}

/**************** Response Handling ****************/
if (res) {
  res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
}

// Reset scroll position when `isRefetching` becomes `true`.
useEffect(() => {
  isRefetching && window.scrollTo(0, 0);
}, [isRefetching]);

